# Verify a detached offline RSA signature before comparing an audit checkpoint.
# Public-key fingerprint MUST come from an independently trusted channel.
# Private signing keys are never imported or generated by this tool.
[CmdletBinding()]
param(
    [Parameter(Mandatory = $true)][ValidateSet('Execution', 'Assessment')][string]$StoreKind,
    [Parameter(Mandatory = $true)][string]$StorePath,
    [Parameter(Mandatory = $true)][string]$CheckpointPath,
    [Parameter(Mandatory = $true)][string]$SignaturePath,
    [Parameter(Mandatory = $true)][string]$PublicKeyPath,
    [Parameter(Mandatory = $true)][string]$ExpectedPublicKeySha256
)
Set-StrictMode -Version 2.0
$ErrorActionPreference = 'Stop'
$script:Utf8 = New-Object Text.UTF8Encoding($false, $true)
$script:AuditVerifier = Join-Path $PSScriptRoot 'Test-SumiGuardAuditIntegrity.ps1'
$script:PowerShell51 = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'

function Test-SumiGuardNoReparse {
    param([Parameter(Mandatory = $true)][string]$Path)
    $full = [IO.Path]::GetFullPath($Path)
    $root = [IO.Path]::GetPathRoot($full)
    $current = $root
    foreach ($part in $full.Substring($root.Length).Split(
        [char[]]@('\', '/'), [StringSplitOptions]::RemoveEmptyEntries)) {
        $current = Join-Path $current $part
        if (-not (Test-Path -LiteralPath $current)) {
            return $false
        }
        $item = Get-Item -LiteralPath $current -Force -ErrorAction Stop
        if (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) {
            return $false
        }
    }
    return $true
}

function Test-SumiGuardWithinStore {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [Parameter(Mandatory = $true)][string]$Store
    )
    $candidate = [IO.Path]::GetFullPath($Path).TrimEnd([char[]]@('\', '/'))
    $base = [IO.Path]::GetFullPath($Store).TrimEnd([char[]]@('\', '/'))
    return [string]::Equals($candidate, $base, [StringComparison]::OrdinalIgnoreCase) -or
        $candidate.StartsWith(
            ($base + [IO.Path]::DirectorySeparatorChar),
            [StringComparison]::OrdinalIgnoreCase)
}

function Read-SumiGuardBoundedFile {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [Parameter(Mandatory = $true)][ValidateRange(1, 65536)][int]$MaximumBytes
    )
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf) -or
        -not (Test-SumiGuardNoReparse -Path $Path)) {
        throw 'INPUT_FILE_INVALID'
    }
    $stream = $null
    try {
        $stream = New-Object IO.FileStream(
            $Path, [IO.FileMode]::Open, [IO.FileAccess]::Read, [IO.FileShare]::Read)
        if ($stream.Length -lt 1 -or $stream.Length -gt $MaximumBytes) {
            throw 'INPUT_FILE_INVALID'
        }
        $length = [int]$stream.Length
        [byte[]]$data = New-Object byte[] $length
        $offset = 0
        while ($offset -lt $length) {
            $count = $stream.Read($data, $offset, $length - $offset)
            if ($count -le 0) { throw 'INPUT_FILE_INVALID' }
            $offset += $count
        }
        if ($stream.Length -ne $length) { throw 'INPUT_FILE_INVALID' }
        return ,$data
    }
    finally {
        if ($null -ne $stream) { $stream.Dispose() }
    }
}

$status = 'VERIFICATION_FAILED'
$reasonCode = $null
$exitCode = 2
$keyPinVerified = $false
$signatureVerified = $false
$storeMatched = $false
$baselineHeld = $null
[byte[]]$checkpointBytes = $null
[byte[]]$keyBytes = $null
[byte[]]$signatureFileBytes = $null
[byte[]]$signatureBytes = $null
[byte[]]$modulus = $null
$rsa = $null
$sha = $null

try {
    if ($ExpectedPublicKeySha256 -cnotmatch '^[0-9a-fA-F]{64}$') {
        throw 'EXPECTED_KEY_PIN_INVALID'
    }
    $store = [IO.Path]::GetFullPath($StorePath).TrimEnd([char[]]@('\', '/'))
    if (-not (Test-Path -LiteralPath $store -PathType Container) -or
        -not (Test-SumiGuardNoReparse -Path $store)) {
        throw 'STORE_INVALID'
    }
    foreach ($inputPath in @($CheckpointPath, $SignaturePath, $PublicKeyPath)) {
        if (Test-SumiGuardWithinStore -Path $inputPath -Store $store) {
            throw 'INPUT_INSIDE_AUDIT_STORE'
        }
    }
    if (-not (Test-Path -LiteralPath $script:AuditVerifier -PathType Leaf) -or
        -not (Test-Path -LiteralPath $script:PowerShell51 -PathType Leaf)) {
        throw 'VERIFIER_UNAVAILABLE'
    }

    $keyBytes = Read-SumiGuardBoundedFile -Path $PublicKeyPath -MaximumBytes 4096
    $sha = [Security.Cryptography.SHA256]::Create()
    $actualPin = ([BitConverter]::ToString($sha.ComputeHash($keyBytes))).Replace('-', '').ToLowerInvariant()
    if ($actualPin -cne $ExpectedPublicKeySha256.ToLowerInvariant()) {
        throw 'PUBLIC_KEY_PIN_MISMATCH'
    }
    $keyPinVerified = $true

    try {
        $publicKey = $script:Utf8.GetString($keyBytes) | ConvertFrom-Json -ErrorAction Stop
        $properties = @($publicKey.PSObject.Properties.Name)
        if ($properties.Count -ne 4) { throw 'PUBLIC_KEY_INVALID' }
        foreach ($property in @('schema_version', 'algorithm', 'modulus_base64', 'exponent_base64')) {
            if ($properties -cnotcontains $property) { throw 'PUBLIC_KEY_INVALID' }
        }
        if ($publicKey.schema_version -isnot [int] -or
            [int]$publicKey.schema_version -ne 1 -or
            [string]$publicKey.algorithm -cne 'RSA-SHA256-PKCS1-v1_5') {
            throw 'PUBLIC_KEY_INVALID'
        }
        if ([string]$publicKey.modulus_base64 -cnotmatch '^[A-Za-z0-9+/]+={0,2}$' -or
            [string]$publicKey.exponent_base64 -cne 'AQAB') {
            throw 'PUBLIC_KEY_INVALID'
        }
        $modulus = [Convert]::FromBase64String([string]$publicKey.modulus_base64)
        if ($modulus.Length -lt 384 -or $modulus.Length -gt 512 -or
            ($modulus.Length % 64) -ne 0 -or $modulus[0] -eq 0) {
            throw 'PUBLIC_KEY_INVALID'
        }
    }
    catch { throw 'PUBLIC_KEY_INVALID' }

    $signatureFileBytes = Read-SumiGuardBoundedFile -Path $SignaturePath -MaximumBytes 8192
    try {
        $signatureText = $script:Utf8.GetString($signatureFileBytes).Trim()
        if ($signatureText -cnotmatch '^[A-Za-z0-9+/]+={0,2}$') {
            throw 'SIGNATURE_FILE_INVALID'
        }
        $signatureBytes = [Convert]::FromBase64String($signatureText)
        if ($signatureBytes.Length -ne $modulus.Length) {
            throw 'SIGNATURE_FILE_INVALID'
        }
    }
    catch { throw 'SIGNATURE_FILE_INVALID' }

    # Retain this read handle through the child comparison to prevent a
    # concurrent writer replacing the signed checkpoint during verification.
    if (-not (Test-Path -LiteralPath $CheckpointPath -PathType Leaf) -or
        -not (Test-SumiGuardNoReparse -Path $CheckpointPath)) {
        throw 'CHECKPOINT_INVALID'
    }
    $baselineHeld = New-Object IO.FileStream(
        ([IO.Path]::GetFullPath($CheckpointPath)),
        [IO.FileMode]::Open, [IO.FileAccess]::Read, [IO.FileShare]::Read)
    if ($baselineHeld.Length -lt 1 -or $baselineHeld.Length -gt 65536) {
        throw 'CHECKPOINT_INVALID'
    }
    $length = [int]$baselineHeld.Length
    $checkpointBytes = New-Object byte[] $length
    $read = 0
    while ($read -lt $length) {
        $got = $baselineHeld.Read($checkpointBytes, $read, $length - $read)
        if ($got -le 0) { throw 'CHECKPOINT_INVALID' }
        $read += $got
    }
    if ($baselineHeld.Length -ne $length) { throw 'CHECKPOINT_INVALID' }

    $publicParameters = New-Object Security.Cryptography.RSAParameters
    $publicParameters.Modulus = $modulus
    $publicParameters.Exponent = [byte[]]@(1, 0, 1)
    $rsa = [Security.Cryptography.RSA]::Create()
    $rsa.ImportParameters($publicParameters)
    $signatureVerified = $rsa.VerifyData(
        $checkpointBytes,
        $signatureBytes,
        [Security.Cryptography.HashAlgorithmName]::SHA256,
        [Security.Cryptography.RSASignaturePadding]::Pkcs1)
    if (-not $signatureVerified) {
        throw 'CHECKPOINT_SIGNATURE_INVALID'
    }

    # The trusted baseline is passed unchanged to the existing read-only
    # verifier. No snapshot, key, signature or store file is written.
    $lines = @(& $script:PowerShell51 -NoLogo -NoProfile -NonInteractive -File $script:AuditVerifier -StoreKind $StoreKind -StorePath $StorePath -Action Compare -BaselinePath $CheckpointPath 2>&1)
    $childExit = $LASTEXITCODE
    $raw = ($lines | Out-String).Trim()
    if ($raw.Length -gt 8192 -or [string]::IsNullOrWhiteSpace($raw)) {
        throw 'AUDIT_COMPARISON_FAILED'
    }
    try { $comparison = $raw | ConvertFrom-Json -ErrorAction Stop }
    catch { throw 'AUDIT_COMPARISON_FAILED' }
    if ($null -eq $comparison -or $comparison.baseline_compared -ne $true) {
        throw 'AUDIT_COMPARISON_FAILED'
    }
    if ($childExit -eq 0 -and $comparison.status -ceq 'MATCHES_SUPPLIED_BASELINE' -and
        $comparison.success -eq $true) {
        $status = 'AUTHENTIC_CHECKPOINT_MATCH'
        $exitCode = 0
        $storeMatched = $true
    }
    elseif ($childExit -eq 1 -and $comparison.status -ceq 'BASELINE_MISMATCH' -and
        $comparison.success -eq $false) {
        $status = 'AUTHENTIC_CHECKPOINT_MISMATCH'
        $exitCode = 1
    }
    else {
        throw 'AUDIT_COMPARISON_FAILED'
    }
}
catch {
    $known = @(
        'EXPECTED_KEY_PIN_INVALID', 'STORE_INVALID', 'INPUT_INSIDE_AUDIT_STORE',
        'VERIFIER_UNAVAILABLE', 'INPUT_FILE_INVALID', 'PUBLIC_KEY_PIN_MISMATCH',
        'PUBLIC_KEY_INVALID', 'SIGNATURE_FILE_INVALID', 'CHECKPOINT_INVALID',
        'CHECKPOINT_SIGNATURE_INVALID', 'AUDIT_COMPARISON_FAILED'
    )
    $reasonCode = if ($known -ccontains [string]$_.Exception.Message) {
        [string]$_.Exception.Message
    } else { 'VERIFICATION_INTERNAL_ERROR' }
    $status = 'VERIFICATION_FAILED'
    $exitCode = 2
}
finally {
    if ($null -ne $rsa) { $rsa.Dispose() }
    if ($null -ne $sha) { $sha.Dispose() }
    if ($null -ne $baselineHeld) { $baselineHeld.Dispose() }
    foreach ($buffer in @($checkpointBytes, $keyBytes, $signatureFileBytes, $signatureBytes, $modulus)) {
        if ($null -ne $buffer -and $buffer.Length -gt 0) {
            [Array]::Clear($buffer, 0, $buffer.Length)
        }
    }
}
[pscustomobject][ordered]@{
    schema_version = 1
    store_kind = $StoreKind
    status = $status
    success = ($exitCode -eq 0)
    key_pin_verified = $keyPinVerified
    checkpoint_signature_verified = $signatureVerified
    store_matches_checkpoint = $storeMatched
    reason_code = $reasonCode
    readonly_verification = $true
    private_key_loaded = $false
    audit_store_modified = $false
} | ConvertTo-Json -Compress -Depth 4
exit $exitCode
